// src/lib/mcp/tools/list-subjects.ts
var list_subjects_default = defineTool2({
  name: "list_subjects",
  title: "List subjects",
  description: "List the subjects for a study track. Defaults to the signed-in learner's own track when no arguments are given.",
  inputSchema: {
    category: z.string().optional().describe("Track category, e.g. 'school', 'entrance' or 'government'."),
    examId: z.string().optional().describe("Exam id, e.g. 'jee', 'neet', 'upsc'."),
    classLevel: z.string().optional().describe("Class level, e.g. 'class-1', 'class-12'."),
    stream: z.string().optional().describe("Stream for senior classes, e.g. 'science'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async (args, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    }
    let { category, examId, classLevel, stream } = args;
    if (!category) {
      const supabase = supabaseForUser(ctx);
      const { data, error } = await supabase.from("user_profiles").select("category, exam_id, class_level, stream").eq("user_id", ctx.getUserId()).maybeSingle();
      if (error) {
        return { content: [{ type: "text", text: error.message }], isError: true };
      }
      if (!data) {
        return {
          content: [
            {
              type: "text",
              text: "No study profile yet \u2014 pass a category (and exam or class) explicitly."
            }
          ],
          isError: true
        };
      }
      category = data.category ?? void 0;
      examId = examId ?? data.exam_id ?? void 0;
      classLevel = classLevel ?? data.class_level ?? void 0;
      stream = stream ?? data.stream ?? void 0;
    }
    if (!category) {
      return { content: [{ type: "text", text: "A category is required." }], isError: true };
    }
    const subjects = getCurriculumSubjects(category, examId, classLevel, stream);
    if (!subjects) {
      return {
        content: [
          {
            type: "text",
            text: "This track uses the fully authored in-app curriculum; browse it inside the app."
          }
        ]
      };
    }
    const list = subjects.map((s) => ({
      id: s.id,
      name: s.name,
      chapterCount: s.chapters.length
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(list) }],
      structuredContent: { track: { category, examId, classLevel, stream }, subjects: list }
    };
  }
});

// src/lib/mcp/tools/list-chapters.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@3.0.4";
import { z as z2 } from "npm:zod@^3.25.76";
var list_chapters_default = defineTool3({
  name: "list_chapters",
  title: "List chapters",
  description: "List the chapters of a subject, with whether each chapter's content is ready yet.",
  inputSchema: {
    subjectId: z2.string().trim().min(1).describe("Subject id returned by list_subjects.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ subjectId }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    }
    const subject = getPlaceholderSubject(subjectId);
    if (!subject) {
      return {
        content: [{ type: "text", text: `No subject found with id "${subjectId}".` }],
        isError: true
      };
    }
    const chapters = subject.chapters.map((c) => ({
      id: c.id,
      name: c.name,
      comingSoon: c.comingSoon === true
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(chapters) }],
      structuredContent: {
        subject: { id: subject.id, name: subject.name },
        chapters
      }
    };
  }
});

